{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles Just Cause Ordinance (JCO)","requirement":"Landlords may not terminate a tenancy without just cause, and owe relocation assistance for no-fault evictions such as owner move-in, demolition, government order to vacate or conversion. A tenant may not be evicted for rent arrears at or below the unit's bedroom-size Fair Market Rent.","key_value":null,"coverage_conditions":"Most residential rentals in the City of Los Angeles not regulated by the City's Rent Stabilization Ordinance; coverage begins after six months' tenancy or lease expiry; can apply to buildings newer than October 1, 1978 and to single-family dwellings.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":"unspecified","min_units":null,"max_units":null,"owner_dependent":true,"other":"Units not regulated by the City's RSO; tenancy covered after six months or expired lease"},"exemptions":"Transient hotels, licensed care facilities, fraternity or sorority houses, owner's roommate, cooperatives under certain circumstances, some non-profit facilities for the homeless or short-term substance-abuse treatment centers, and some properties owned by HACLA or the government.","penalty":null,"effective_date":null,"citation":"Los Angeles Just Cause Ordinance (L.A.M.C. §165.00 et seq.)","quoted_span":"It prohibits terminations of tenancies without just cause and requires relocation assistance for no-fault evictions.","interaction":"Covers units that are not regulated by the City's Rent Stabilization Ordinance (RSO).","confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"CA","category":"rent_increase_limits","lifecycle":"enacted","title":"California Tenant Protection Act (AB 1482) annual rent cap","requirement":"Annual rent increases for covered units are capped at 5% plus the regional cost-of-living change, or 10%, whichever is lower; the maximum allowable increase was 8.9% from August 1, 2024 to July 31, 2025.","key_value":"5% + CPI, max 10%; 8.9% for Aug 1, 2024–Jul 31, 2025","coverage_conditions":"Units more than 15 years old on a rolling basis; single-family homes and condominiums unless owned by a real estate trust, corporation or LLC with a corporate member and the tenant was notified in writing.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":true,"other":"Units older than 15 years, determined on a rolling basis"},"exemptions":"Units built within the last 15 years; deed-restricted or regulatory-agreement affordable units; certain dormitories; a two-unit property where the owner occupied the second unit throughout the tenancy; single-family homes and condominiums meeting the ownership and notice conditions; units already under the City's RSO.","penalty":null,"effective_date":"2024-08-01","citation":"Cal. Civ. Code § 1947.12","quoted_span":"Effective August 1, 2024 to July 31, 2025, the maximum allowable increase is 8.9%.","interaction":"The JCO does not regulate rent increases; this state cap may govern buildings older than 15 years.","confidence":0.75,"conflict_flag":false,"conflict_note":null}
